// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadCaveat = makeLoadFont('Caveat');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: caveatFamily } = loadCaveat();



export type ContractOverlayProps = Record<string, any>;

const ContractOverlay: React.FC<ContractOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  paperColor = "#fdfdfc",
  textColor = "#1f2937",
  accentColor = "#9ca3af",
  signatureColor = "#1d4ed8",
  sealColor = "#b45309",
  contractTitle = "NON-DISCLOSURE AGREEMENT",
  partyOne = "Malloy Studio",
  partyTwo = "Client Representative",
  signatureName = "Malloy Studio",
  clauseLinesCount = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Dimensions
  const paperWidth = Math.min(width * 0.85, 800);
  const paperHeight = height * 0.75;
  const paddingX = paperWidth * 0.1;
  const paddingY = paperHeight * 0.08;

  // --- Animations ---

  // 1. Paper Entry
  const paperEntrySpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 100 },
  });
  
  const paperY = interpolate(paperEntrySpring, [0, 1], [height, (height - paperHeight) / 2]);
  const paperRotation = interpolate(paperEntrySpring, [0, 1], [5, -1]);

  // 2. Content Fade & Slide
  const contentStartFrame = 15;
  const contentOpacity = interpolate(
    frame - contentStartFrame,
    [0, 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const contentYOffset = interpolate(
    frame - contentStartFrame,
    [0, 15],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Seal Stamp
  const sealStartFrame = 50;
  const sealSpring = spring({
    frame: frame - sealStartFrame,
    fps,
    config: { damping: 10, mass: 1, stiffness: 150 },
  });
  const sealScale = interpolate(sealSpring, [0, 1], [2, 1]);
  const sealOpacity = interpolate(sealSpring, [0, 1], [0, 0.9]);

  // 4. Writing Animation (Signature & Pen)
  const writeStartFrame = 70;
  const writeDuration = 60;
  const writeEndFrame = writeStartFrame + writeDuration;
  
  // Progress from 100% to 0% for the clip-path inset (revealing left to right)
  const writeProgress = interpolate(
    frame,
    [writeStartFrame, writeEndFrame],
    [100, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Pen movement
  const signatureAreaWidth = paperWidth * 0.6;
  const penXBase = interpolate(
    frame,
    [writeStartFrame, writeEndFrame],
    [0, signatureAreaWidth * 0.8],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Sine wave for writing motion, only active during writing frames
  const isWriting = frame >= writeStartFrame && frame <= writeEndFrame;
  const writingSine = isWriting ? Math.sin((frame - writeStartFrame) * 1.8) * 8 : 0;
  const writingCosine = isWriting ? Math.cos((frame - writeStartFrame) * 1.2) * 4 : 0;

  const penX = penXBase + writingCosine;
  const penY = writingSine;

  // Pen Enter/Exit logic
  const penEnterOpacity = interpolate(
    frame,
    [writeStartFrame - 10, writeStartFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const penExitOpacity = interpolate(
    frame,
    [writeEndFrame, writeEndFrame + 15],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const finalPenOpacity = frame > writeEndFrame ? penExitOpacity : penEnterOpacity;

  const penEnterYOffset = interpolate(
    frame,
    [writeStartFrame - 10, writeStartFrame],
    [-30, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const penExitXOffset = interpolate(
    frame,
    [writeEndFrame, writeEndFrame + 15],
    [0, 40],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const penExitYOffset = interpolate(
    frame,
    [writeEndFrame, writeEndFrame + 15],
    [0, -20],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const totalPenX = penX + (frame > writeEndFrame ? penExitXOffset : 0);
  const totalPenY = penY + (frame < writeStartFrame ? penEnterYOffset : (frame > writeEndFrame ? penExitYOffset : 0));


  // Static layout variations for mock lines to avoid randomness
  const lineVariations = [0.95, 0.85, 1.0, 0.75, 0.9, 0.6, 0.95, 0.8, 1.0, 0.7];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      
      {/* Paper Container */}
      <div
        style={{
          position: "absolute",
          width: paperWidth,
          height: paperHeight,
          backgroundColor: paperColor,
          borderRadius: 8,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
          transform: `translateY(${paperY}px) rotate(${paperRotation}deg)`,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          padding: `${paddingY}px ${paddingX}px`,
          boxSizing: "border-box",
        }}
      >
        {/* Content Wrapper for Fade/Slide */}
        <div
          style={{
            opacity: contentOpacity,
            transform: `translateY(${contentYOffset}px)`,
            display: "flex",
            flexDirection: "column",
            flex: 1,
          }}
        >
          {/* Header */}
          <div style={{ borderBottom: `2px solid ${accentColor}40`, paddingBottom: 20, marginBottom: 30 }}>
            <h1
              style={{
                fontFamily: playfairFamily,
                fontSize: 42,
                color: textColor,
                margin: 0,
                textAlign: "center",
                fontWeight: 700,
                letterSpacing: "0.05em",
              }}
            >
              {contractTitle}
            </h1>
          </div>

          {/* Parties */}
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 40, fontFamily: interFamily }}>
            <div>
              <div style={{ fontSize: 14, color: accentColor, textTransform: "uppercase", letterSpacing: 1, marginBottom: 4 }}>Party One</div>
              <div style={{ fontSize: 20, color: textColor, fontWeight: 600 }}>{partyOne}</div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 14, color: accentColor, textTransform: "uppercase", letterSpacing: 1, marginBottom: 4 }}>Party Two</div>
              <div style={{ fontSize: 20, color: textColor, fontWeight: 600 }}>{partyTwo}</div>
            </div>
          </div>

          {/* Clauses (Simulated Lines) */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 16 }}>
            {Array.from({ length: clauseLinesCount }).map((_, i) => {
              const lineStartFrame = contentStartFrame + 10 + i * 3;
              const lineOpacity = interpolate(
                frame,
                [lineStartFrame, lineStartFrame + 10],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );
              const lineWidthPct = lineVariations[i % lineVariations.length] * 100;
              
              return (
                <div key={i} style={{ opacity: lineOpacity, display: "flex", flexDirection: "column", gap: 8 }}>
                  <div style={{ height: 10, width: `${lineWidthPct}%`, backgroundColor: `${accentColor}30`, borderRadius: 5 }} />
                  {i % 2 === 0 && (
                    <div style={{ height: 10, width: `${lineWidthPct * 0.8}%`, backgroundColor: `${accentColor}20`, borderRadius: 5 }} />
                  )}
                </div>
              );
            })}
          </div>

          {/* Footer Area: Signature & Seal */}
          <div style={{ position: "relative", height: 200, marginTop: "auto", display: "flex", alignItems: "flex-end" }}>
            
            {/* Seal */}
            <div
              style={{
                position: "absolute",
                left: 0,
                bottom: 20,
                width: 120,
                height: 120,
                transform: `scale(${sealScale})`,
                opacity: sealOpacity,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              {/* Outer dashed ring */}
              <div style={{ position: "absolute", width: "100%", height: "100%", borderRadius: "50%", border: `4px dashed ${sealColor}`, opacity: 0.7 }} />
              {/* Inner solid circle */}
              <div style={{ width: "75%", height: "75%", borderRadius: "50%", backgroundColor: sealColor, opacity: 0.9, display: "flex", justifyContent: "center", alignItems: "center" }}>
                <div style={{ color: paperColor, fontFamily: playfairFamily, fontSize: 16, fontWeight: "bold", letterSpacing: 2 }}>SEAL</div>
              </div>
            </div>

            {/* Signature Block */}
            <div style={{ marginLeft: "auto", width: signatureAreaWidth, borderBottom: `2px solid ${textColor}`, paddingBottom: 10, position: "relative" }}>
              
              <div style={{ position: "absolute", bottom: -25, right: 0, fontFamily: interFamily, fontSize: 14, color: accentColor, textTransform: "uppercase", letterSpacing: 1 }}>
                Authorized Signature
              </div>

              {/* The Written Signature */}
              <div
                style={{
                  fontFamily: caveatFamily,
                  fontSize: 72,
                  color: signatureColor,
                  lineHeight: 1,
                  transform: "rotate(-5deg)",
                  transformOrigin: "bottom left",
                  clipPath: `inset(0 ${writeProgress}% 0 0)`, // Reveals from left to right
                  paddingLeft: 20,
                  whiteSpace: "nowrap",
                }}
              >
                {signatureName}
              </div>

              {/* The Pen Icon */}
              <div
                style={{
                  position: "absolute",
                  bottom: 20,
                  left: 10,
                  opacity: finalPenOpacity,
                  transform: `translate(${totalPenX}px, ${totalPenY}px)`,
                  zIndex: 10,
                  pointerEvents: "none",
                }}
              >
                <svg width="64" height="64" viewBox="0 0 24 24" fill={textColor} style={{ filter: "drop-shadow(3px 5px 4px rgba(0,0,0,0.2))" }}>
                  <path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" />
                </svg>
              </div>

            </div>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ContractOverlay;